import test from 'node:test';import assert from'node:assert/strict';import{AutomataMesh,CapabilityTray,MorphingWorkspace,conversationAutomaton,successAutomaton}from'../src/index.mjs';
test('success is a working sovereign Automaton using person-defined direction',async()=>{const success=successAutomaton();await success.call({type:'define',personId:'p',purpose:{statement:'Live my purpose',indicators:[{id:'practice',name:'Practice',direction:'increase'}]}});await success.call({type:'observe',personId:'p',indicatorId:'practice',value:1,context:{source:'person'}});const progress=await success.call({type:'observe',personId:'p',indicatorId:'practice',value:3,context:{source:'person'}});assert.equal(progress.direction,'toward');const summary=await success.call({type:'summary',personId:'p'});assert.equal(summary.purpose.statement,'Live my purpose');});
test('capability tray is generated from mounted Automatons rather than hard-coded apps',()=>{const mesh=new AutomataMesh();mesh.add(conversationAutomaton());mesh.add(successAutomaton());const workspace=new MorphingWorkspace({views:[{id:'chat',type:'conversation',state:{}}],focus:'chat'});const tray=new CapabilityTray().resolve({mesh,workspace,context:{mode:'conversation'},notifications:[{id:'n'}]});assert.equal(tray.form,'bottom-sheet');assert.deepEqual(tray.items.map(item=>item.id),['conversation','success']);assert.equal(tray.anchors.notifications,1);});
test('tray form can morph by context while invariant anchors remain',()=>{const mesh=new AutomataMesh();mesh.add(successAutomaton());const workspace=new MorphingWorkspace({views:[]});const resolver=new CapabilityTray({formResolver:({context})=>context.mode==='focus'?'compact':'radial'});const a=resolver.resolve({mesh,workspace,context:{mode:'focus'}}),b=resolver.resolve({mesh,workspace,context:{mode:'explore'}});assert.equal(a.form,'compact');assert.equal(b.form,'radial');assert.equal(a.anchors.controls,true);assert.equal(b.anchors.presence,'companion');});
